arguments.command:
curl -sS https://api.linear.app/graphql -H "Authorization: <TOKEN>" -H "Content-Type: application/json" -d '{"query":"{ __schema { queryType { fields { name args { name type { kind name ofType { kind name } } } } } mutationType { fields { name } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)['data']['__schema']
for f in d['queryType']['fields']:
    if f['name'] in ('cycles','cycle'):
        print('QUERY', f['name'], [(a['name'], a['type']) for a in f['args']])
for f in d['mutationType']['fields']:
    if 'cycle' in f['name'].lower():
        print('MUTATION', f['name'])
"

